using AutoKeyframe;using Timeline;using UnityEngine;using System.Text.Json;
var rows=new List<object>();int failures=0;
void Check(bool p,string reason){if(!p)throw new Exception(reason);}
void Test(string name,Action run){Debug.Warnings.Clear();Debug.Messages.Clear();try{run();rows.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failures++;rows.Add(new{name,passed=false,error=e.GetType().Name+": "+e.Message});Console.WriteLine("FAIL "+name+": "+e.GetType().Name);}}
(Timeline.Timeline timeline,Interpolable track,Keyframe frame) Setup(object? old,Func<object?> source){var t=new Timeline.Timeline();var i=new Interpolable{Source=source};var f=new Keyframe{value=old};t.Current.Add(new(i,f));return(t,i,f);}
var service=new KeyframeService();
Test("null reference preserves original keyframe identity",()=>{var old=new float[]{1,2};var x=Setup(old,()=>throw new NullReferenceException());service.UpdateChangedKeyframes(x.timeline);Check(ReferenceEquals(old,x.frame.value),"original value changed");});
Test("missing native object preserves value",()=>{var x=Setup(7f,()=>throw new MissingReferenceException());service.UpdateChangedKeyframes(x.timeline);Check(Equals(x.frame.value,7f),"lost old value");});
Test("one invalid track does not block subsequent healthy track",()=>{var x=Setup(7,()=>throw new NullReferenceException());var f=new Keyframe{value=8};x.timeline.Current.Add(new(new Interpolable{Source=()=>9},f));service.UpdateChangedKeyframes(x.timeline);Check(Equals(f.value,9)&&Equals(x.frame.value,7),"healthy track blocked");});
Test("repeat missing source emits one warning until recovery",()=>{var x=Setup(7,()=>throw new NullReferenceException());for(int n=0;n<5;n++)service.UpdateChangedKeyframes(x.timeline);Check(Debug.Warnings.Count==1,"warning spam or missing warning");});
Test("recovery resumes updates and permits a later failure notice",()=>{var x=Setup(7,()=>throw new NullReferenceException());service.UpdateChangedKeyframes(x.timeline);x.track.Source=()=>8;service.UpdateChangedKeyframes(x.timeline);Check(Equals(x.frame.value,8)&&Debug.Messages.Count==1,"recovery lost");x.track.Source=()=>throw new NullReferenceException();service.UpdateChangedKeyframes(x.timeline);Check(Equals(x.frame.value,8)&&Debug.Warnings.Count==2,"second outage not reported");});
Test("independent failed tracks receive distinct notices",()=>{var a=Setup(1,()=>throw new NullReferenceException());var b=Setup(2,()=>throw new NullReferenceException());service.UpdateChangedKeyframes(a.timeline);service.UpdateChangedKeyframes(b.timeline);Check(Debug.Warnings.Count==2,"distinct source missing");});
Test("valid zero and false still write",()=>{var a=Setup(9,()=>0);service.UpdateChangedKeyframes(a.timeline);Check(Equals(a.frame.value,0),"zero rejected");var b=Setup(true,()=>false);service.UpdateChangedKeyframes(b.timeline);Check(Equals(b.frame.value,false),"false rejected");});
Test("valid null callback retains original semantics",()=>{var a=Setup(9,()=>null);service.UpdateChangedKeyframes(a.timeline);Check(a.frame.value==null,"valid null rejected");});
Test("null old value remains null on unavailable read",()=>{var a=Setup(null,()=>throw new NullReferenceException());service.UpdateChangedKeyframes(a.timeline);Check(a.frame.value==null,"invented value");});
Test("unexpected exceptions propagate",()=>{var a=Setup(9,()=>throw new InvalidOperationException("unexpected"));bool threw=false;try{service.UpdateChangedKeyframes(a.timeline);}catch(InvalidOperationException){threw=true;}Check(threw&&Equals(a.frame.value,9)&&Debug.Warnings.Count==0,"exception swallowed");});
Test("unchanged identity and empty timeline remain intact",()=>{var old=new object();var a=Setup(old,()=>old);service.UpdateChangedKeyframes(a.timeline);service.UpdateChangedKeyframes(new Timeline.Timeline());Check(ReferenceEquals(old,a.frame.value)&&Debug.Warnings.Count==0,"changed intact data");});
Console.WriteLine($"checks={rows.Count} failures={failures}");if(args.Length>0)File.WriteAllText(args[0],JsonSerializer.Serialize(new{checks=rows.Count,failures,results=rows},new JsonSerializerOptions{WriteIndented=true}));return failures==0?0:1;
